/bin/bash -lc "npm test && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createApp } from './src/app.js';
const accounts = [{ id: 'a1', name: 'Ada' }];
const auditEvents = [];
const app = createApp({ accounts, auditEvents });
const response = await app.request('POST', '/accounts/a1/suspend');
assert.equal(response.status, 200);
assert.equal(response.body.state, 'suspended');
assert.equal(accounts[0].state, 'suspended');
assert.deepEqual(auditEvents, [{ type: 'account.suspended', accountId: 'a1' }]);
assert.equal((await app.request('GET', '/accounts/a1')).body.state, 'suspended');
assert.equal((await app.request('POST', '/accounts/missing/suspend')).status, 404);
assert.equal(auditEvents.length, 1);
console.log('suspension flow verified');
NODE"

